        if ($value instanceof self) {
            return $value->label();
        }

        return is_scalar($value) ? (self::tryFrom((string) $value)?->label() ?? '—') : '—';
    }

    /** @return array<int, GradeType> */
    public static function continuous(): array
    {
        return [self::Continuous, self::Homework];
    }
