        // پنل مدیریت منو و سایه دارد و روی کاغذ می‌افتد؛ سند رسمی باید تمیز باشد
        $this->actingAsRole(Role::Admin);

        $response = $this->get($this->url(Student::factory()->create()));

        $response->assertOk();
        $response->assertDontSee('drawer-side');
        $response->assertDontSee('خروج از حساب');
    }

    public function test_the_transcript_carries_the_academy_header_and_the_document_number(): void
    {
        $this->actingAsRole(Role::Admin);
        Setting::put(Setting::ACADEMY_NAME, 'آموزشگاه دانش‌نویس');
        $student = $this->enrolledStudent(Course::factory()->create());

        $this->get($this->url($student))
            ->assertOk()
            ->assertSee('آموزشگاه دانش‌نویس')
            ->assertSee('کارنامه رسمی')
            ->assertSee('شماره سند');
    }

    public function test_the_document_number_is_stable_for_one_student_and_differs_per_student(): void
    {
        // شماره‌ای که با هر چاپ عوض شود به پروندهٔ شکایت اجازه نمی‌دهد به یک
        // سند واحد اشاره کند، و شمارهٔ یکسان برای دو دانش‌آموز یعنی «کدام
        // کارنامه؟» — هر دو باید درست باشند
        $this->actingAsRole(Role::Admin);

        $first = $this->enrolledStudent(Course::factory()->create());
        $second = $this->enrolledStudent(Course::factory()->create());

        $one = $this->get($this->url($first))->assertOk()->getContent();
        $two = $this->get($this->url($first))->assertOk()->getContent();
        $three = $this->get($this->url($second))->assertOk()->getContent();

        preg_match('/شماره سند:\s*([A-Za-z0-9\-]+)/u', strip_tags($one), $matches);
        $number = $matches[1] ?? '';

        $this->assertNotSame('', $number);
        $this->assertStringContainsString($number, strip_tags($two));
        $this->assertStringNotContainsString($number, strip_tags($three));
    }

    // ── محتوا ──────────────────────────────────────────────

    public function test_the_transcript_lists_every_confirmed_course_with_its_final_score(): void
    {
        $this->actingAsRole(Role::Admin);
        $course = Course::factory()->create(['title' => 'ریاضی یازدهم']);
        $student = $this->enrolledStudent($course);
        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 16);

        $this->get($this->url($student))
            ->assertOk()
            ->assertSee('ریاضی یازدهم')
            ->assertSee(to_persian_digits('16.00'))
            ->assertSee(to_persian_digits('20.00'));
    }

    public function test_the_transcript_shows_the_raw_grades_under_each_course(): void
    {
        // نمرهٔ نهایی به‌تنهایی قابل بازبینی نیست؛ خانواده وقتی شکایت می‌کند
        // باید ببیند نمره از کجا آمده است
        $this->actingAsRole(Role::Admin);
        $course = Course::factory()->create();
        $student = $this->enrolledStudent($course);
        Grade::record($student, $course, GradeType::Homework, 'تکلیف ۳', 18, maxScore: 20);
        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 15);

        $this->get($this->url($student))
            ->assertOk()
            ->assertSee('ریزنمرات')
            ->assertSee('تکلیف ۳')
            ->assertSee('پایان‌ترم')
            ->assertSee(to_persian_digits('18.00/20.00'))
            ->assertSee(to_persian_digits('15.00/20.00'));
    }

    public function test_the_transcript_reports_the_attended_hours(): void
    {
        $this->actingAsRole(Role::Admin);
        $course = Course::factory()->create(['session_count' => 10, 'session_duration' => 90]);
        $student = $this->enrolledStudent($course);
        $session = $this->sessionFor($course);

        // جلسه‌ای که برگزار شده ولی دانش‌آموز غایب بوده، ساعت حضور نمی‌شود
        Attendance::recordFor($session, [
            ['student_id' => $student->id, 'status' => AttendanceStatus::Present->value],
        ]);

        $this->get($this->url($student))
            ->assertOk()
            ->assertSee(to_persian_digits('2.0'))
            ->assertSee(to_persian_digits('15.0'));
    }

    public function test_a_absent_session_does_not_count_as_attended_hours(): void
    {
        $this->actingAsRole(Role::Admin);
        $course = Course::factory()->create();
        $student = $this->enrolledStudent($course);
        Attendance::recordFor($this->sessionFor($course), [
            ['student_id' => $student->id, 'status' => AttendanceStatus::Absent->value],
        ]);

        $this->get($this->url($student))
            ->assertOk()
            ->assertSee(to_persian_digits('0.0'));
    }

    public function test_a_course_below_the_pass_mark_is_marked_failed(): void
    {
        $this->actingAsRole(Role::Admin);
        $course = Course::factory()->create(['title' => 'فیزیک دوازدهم']);
        $student = $this->enrolledStudent($course);
        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 8);

        $this->get($this->url($student))
            ->assertOk()
