    public function test_a_course_at_or_above_the_pass_mark_is_marked_passed(): void
    {
        $this->actingAsRole(Role::Admin);
        $course = Course::factory()->create();
        $student = $this->enrolledStudent($course);
        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 10);

        $this->get($this->url($student))->assertOk()->assertSee('قبول');
