    public function test_the_average_of_the_final_scores_is_printed(): void
    {
        $this->actingAsRole(Role::Admin);
        $first = Course::factory()->create(['title' => 'دوره اول']);
        $second = Course::factory()->create(['title' => 'دوره دوم']);
        $student = $this->enrolledStudent($first);
        CourseEnrollment::enroll($student, $second)->confirm();

        Grade::record($student, $first, GradeType::Final, 'پایان‌ترم', 16);
        Grade::record($student, $second, GradeType::Final, 'پایان‌ترم', 12);

        $this->get($this->url($student))
            ->assertOk()
            ->assertSee(to_persian_digits('14.00'));
    }

    public function test_the_issue_date_is_printed_in_shamsi(): void
    {
        $this->actingAsRole(Role::Admin);
        $student = $this->enrolledStudent(Course::factory()->create());

        // تاریخ میلادی روی سند رسمی برای خانواده بی‌معناست
        $this->get($this->url($student))
            ->assertOk()
            ->assertSee(jalali_date(now()))
            ->assertDontSee(now()->toDateString());
