    public function test_a_student_without_grades_gets_a_document_that_says_no_record(): void
    {
        // ثبت‌نام قطعی هست ولی نمره‌ای ثبت نشده: سند باید صادر شود نه بشکند،
        // و «فاقد سابقه» بگوید — سکوت یعنی خانواده فکر می‌کند نمره گم شده است
        $this->actingAsRole(Role::Admin);
        $course = Course::factory()->create(['title' => 'شیمی یازدهم']);
        $student = $this->enrolledStudent($course);

        $this->get($this->url($student))
            ->assertOk()
            ->assertSee('شیمی یازدهم')
            ->assertSee('فاقد سابقه');
    }

    public function test_a_student_without_any_enrollment_still_gets_a_document(): void
    {
        $this->actingAsRole(Role::Admin);
        $student = Student::factory()->create();

        $this->get($this->url($student))
            ->assertOk()
            ->assertSee('کارنامه رسمی')
            ->assertSee('فاقد سابقه');
    }

    // ── دسترسی ─────────────────────────────────────────────

    public function test_finance_and_reception_cannot_print_a_transcript(): void
    {
        // این دو پرونده را باز می‌کنند ولی نمره کار آن‌ها نیست
        $student = Student::factory()->create();

        foreach ([Role::Finance, Role::Reception] as $role) {
            $this->actingAs($this->actingAsRole($role));
            $this->get($this->url($student))->assertForbidden();
        }
    }

    public function test_a_teacher_cannot_print_a_transcript(): void
    {
        // دبیر پروندهٔ عمومی باز نمی‌کند؛ همان قاعدهٔ صفحهٔ پرونده
        $this->actingAsRole(Role::Teacher);

        $this->get($this->url(Student::factory()->create()))->assertForbidden();
    }

    public function test_a_guest_is_sent_to_login(): void
    {
        $this->get($this->url(Student::factory()->create()))
            ->assertRedirect(route('login'));
    }

    public function test_the_profile_page_offers_the_transcript_only_to_roles_that_see_grades(): void
    {
        $student = Student::factory()->create();

        $this->actingAsRole(Role::Deputy);

        Livewire::test('pages::students.show', ['student' => $student->id])
            ->assertSee('کارنامه رسمی');

        $this->actingAsRole(Role::Reception);

        Livewire::test('pages::students.show', ['student' => $student->id])
            ->assertDontSee('کارنامه رسمی');
    }
